fn CURLY_LDQUO() -> String {
    return char::from_u32((8220) as u32).unwrap_or('\u{0}').to_string();
}

fn CURLY_RDQUO() -> String {
    return char::from_u32((8221) as u32).unwrap_or('\u{0}').to_string();
}

