fn smartQuotes(s: &str) -> String {
    let mut out: String = "".to_string();
    let mut i: i64 = 0;
    let sLen: i64 = (s.chars().count() as i64);
    while i < sLen {
        let cs = s.chars().take((i + 1) as usize).skip((i) as usize).collect::<String>();
        if cs == "\"" {
            let mut prevIsOpenCtx: bool = false;
            if out == "" {
                prevIsOpenCtx = true;
            } else {
                let prev = out.chars().take(((out.chars().count() as i64)) as usize).skip(((out.chars().count() as i64) - 1) as usize).collect::<String>();
                if prev == " " {
                    prevIsOpenCtx = true;
                }                if prev == "\n" {
                    prevIsOpenCtx = true;
                }                if prev == "(" {
                    prevIsOpenCtx = true;
                }                if prev == "[" {
                    prevIsOpenCtx = true;
                }                if prev == "{" {
                    prevIsOpenCtx = true;
                }            }
            if prevIsOpenCtx {
                out += &CURLY_LDQUO();
                i += 1;
                continue;
            }            

            if i + 1 >= (s.chars().count() as i64) {
                out += &CURLY_RDQUO();
                i += 1;
                continue;
            }            let nc = s.chars().nth((i + 1) as usize).unwrap_or('\0') as i64;
            if nc == 32 {
                out += &CURLY_RDQUO();
            } else {
                if nc == 10 {
                    out += &CURLY_RDQUO();
                } else {
                    if isClosePunctCode(nc) {
                        out += &CURLY_RDQUO();
                    } else {
                        out += &cs;
                    }
                }
            }
            i += 1;
            continue;
        }
        if cs == "'" {
            let mut apostrophe: bool = false;
            if i > 0 {
                if i + 1 < (s.chars().count() as i64) {
                    let pc = s.chars().nth((i - 1) as usize).unwrap_or('\0') as i64;
                    let ncc = s.chars().nth((i + 1) as usize).unwrap_or('\0') as i64;
                    let pWord = isWordCharCode(pc);
                    let nWord = isWordCharCode(ncc);
                    if pWord {
                        if nWord {
                            apostrophe = true;
                        }                    }                }            }            if apostrophe {
                out += &CURLY_RSQUO();
            } else {
                let mut openS: bool = false;
                if out == "" {
                    openS = true;
                } else {
                    let prev2 = out.chars().take(((out.chars().count() as i64)) as usize).skip(((out.chars().count() as i64) - 1) as usize).collect::<String>();
                    if prev2 == " " {
                        openS = true;
                    }                    if prev2 == "\n" {
                        openS = true;
                    }                    if prev2 == "(" {
                        openS = true;
                    }                    if prev2 == "[" {
                        openS = true;
                    }                }
                if openS {
                    out += &CURLY_LSQUO();
                } else {
                    out += &CURLY_RSQUO();
                }
            }
            i += 1;
            continue;
        }
        out += &cs;
        i += 1;
    }
    return out;
}

fn isNestingDelimCode(c: i64) -> bool {
    if c == 42 {
        return true;
    }
    return c == 95;
}

fn scanDelim(line: &str, i: i64, delim: &str, autoCloseWhenFinal: bool, isFinal: bool) -> Option<DelimScan> {



    if delim == "_" {
        if i > 0 {
            let pc = line.chars().nth((i - 1) as usize).unwrap_or('\0') as i64;
            if isWordCharCode(pc) {
                return None;
            }        }    }
    if delim == "__" {
        if i > 0 {
            let pc2 = line.chars().nth((i - 1) as usize).unwrap_or('\0') as i64;
            if isWordCharCode(pc2) {
                return None;
            }        }    }
    if delim == "___" {
        if i > 0 {
            let pc3 = line.chars().nth((i - 1) as usize).unwrap_or('\0') as i64;
            if isWordCharCode(pc3) {
                return None;
            }        }    }
    let afterStart: i64 = i + (delim.chars().count() as i64);
    let inner = line.chars().skip((afterStart) as usize).collect::<String>();
    let mut close = findStr(inner.as_str(), delim);
    let mut innerText = inner.clone();
    if close != -1 {
        innerText = inner.chars().take((close) as usize).skip((0) as usize).collect::<String>();
    }
    if innerText == "" {
        

        return None;
    }
    if isPunctuationCode(innerText.chars().nth((0) as usize).unwrap_or('\0') as i64) {
        






        let mut nest: bool = false;
        if close != -1 {
            if isNestingDelimCode(innerText.chars().nth((0) as usize).unwrap_or('\0') as i64) {
                nest = true;
            }        }        if !(nest) {
            return None;
        }    }
    if close != -1 {
        let mut next: i64 = afterStart + close + (delim.chars().count() as i64);
        return Some(DelimScan { next: next, inner: innerText.to_string() });
    }
    if !(autoCloseWhenFinal) {
        if isFinal {
            return None;
        }    }

    if inner == "" {
        return None;
    }
    if inner.chars().nth((0) as usize).unwrap_or('\0') as i64 == 32 {
        return None;
    }
    return Some(DelimScan { next: (line.chars().count() as i64), inner: inner.to_string() });
}

fn findBacktickRun(line: &str, from: i64, count: i64) -> i64 {
    let mut i: i64 = from;
    while i < (line.chars().count() as i64) {
        if line.chars().nth((i) as usize).unwrap_or('\0') as i64 != 96 {
            i += 1;
            continue;
        }
        let mut run: i64 = 0;
        while startsWithAt(line, "`", i + run) {
            run += 1;
        }
        if run == count {
            return i;
        }
        i += run;
    }
    return -1;
}

fn stripTrailingUrlPunct(s: &str) -> String {
    let mut end: i64 = (s.chars().count() as i64);
    while end > 0 {
        let c = s.chars().nth((end - 1) as usize).unwrap_or('\0') as i64;
        if c == 46 {
            end -= 1;
        } else {
            if c == 44 {
                end -= 1;
            } else {
                if c == 58 {
                    end -= 1;
                } else {
                    if c == 59 {
                        end -= 1;
                    } else {
                        if c == 33 {
                            end -= 1;
                        } else {
                            if c == 63 {
                                end -= 1;
                            } else {
                                if c == 41 {
                                    end -= 1;
                                } else {
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

    }
    if end == (s.chars().count() as i64) {
        return s.to_string();
    }
    return s.chars().take((end) as usize).skip((0) as usize).collect::<String>().to_string();
}

fn isHttpUrl(s: &str) -> bool {
    if startsWithStr(s, "http://") {
        if (s.chars().count() as i64) > 7 {
            return true;
        }    }
    if startsWithStr(s, "https://") {
        if (s.chars().count() as i64) > 8 {
            return true;
        }    }
    return false;
}

fn isBareDomain(s: &str) -> bool {
    if (s.chars().count() as i64) == 0 {
        return false;
    }
    let mut dot: i64 = -1;
    let mut i: i64 = 0;
    while i < (s.chars().count() as i64) {
        let c = s.chars().nth((i) as usize).unwrap_or('\0') as i64;
        let mut ok: bool = false;
        if c >= 48 {
            if c <= 57 {
                ok = true;
            }        }
        if c >= 65 {
            if c <= 90 {
                ok = true;
            }        }
        if c >= 97 {
            if c <= 122 {
                ok = true;
            }        }
        if c == 45 {
            ok = true;
        }
        if c == 46 {
            ok = true;
            dot = i;
        }
        if !(ok) {
            return false;
        }
        i += 1;
    }
    if dot <= 0 {
        return false;
    }
    let mut letters: i64 = 0;
    let mut j: i64 = dot + 1;
    while j < (s.chars().count() as i64) {
        let c = s.chars().nth((j) as usize).unwrap_or('\0') as i64;
        if c >= 65 {
            if c <= 90 {
                letters += 1;
            } else {
                return false;
            }
        } else {
            if c >= 97 {
                if c <= 122 {
                    letters += 1;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }

        j += 1;
    }
    if letters < 2 {
        return false;
    }
    return true;
}

fn scanLink(line: &str, i: i64, isFinal: bool, seenCode: bool) -> Option<LinkScan> {
    let mut close = findStrFrom(line, "]", i);
    if close == -1 {
        return None;
    }
    let text = line.chars().take((close) as usize).skip((i + 1) as usize).collect::<String>();
    let mut after: i64 = close + 1;
    if !(startsWithAt(line, "(", after)) {
        return None;
    }
    let mut end = findStrFrom(line, ")", after);
    if end == -1 {
        



        let frag = line.chars().skip((after + 1) as usize).collect::<String>();
        if isHttpUrl(frag.as_str()) {
            let mut urlHref = stripTrailingUrlPunct(frag.as_str());
            let mut tailText = frag.chars().skip(((urlHref.chars().count() as i64)) as usize).collect::<String>();
            let mut urlTitle: Option<String> = Some("".to_string());
            if seenCode {
                urlTitle = None;
            }            return Some(LinkScan { next: (line.chars().count() as i64), text: text.to_string(), href: urlHref.to_string(), loading: true, title: urlTitle, tail: tailText.to_string() });
        }        if isBareDomain(frag.as_str()) {
            return Some(LinkScan { next: (line.chars().count() as i64), text: text.to_string(), href: format!("{}{}", "http://", frag).to_string(), loading: true, title: None, tail: "".to_string() });
        }        return Some(LinkScan { next: (line.chars().count() as i64), text: text.to_string(), href: "".to_string(), loading: true, title: None, tail: "".to_string() });
    }
    let mut inner = line.chars().take((end) as usize).skip((after + 1) as usize).collect::<String>();
    let mut href = inner.clone();
    let mut title: Option<String> = None;
    let sp = findStr(inner.as_str(), " \"");
    if sp != -1 {
        href = inner.chars().take((sp) as usize).skip((0) as usize).collect::<String>();
        let titlePart = inner.chars().skip((sp + 2) as usize).collect::<String>();
        if endsWithTokSeq(titlePart.as_str(), "\"") {
            title = Some(titlePart.chars().take(((titlePart.chars().count() as i64) - 1) as usize).skip((0) as usize).collect::<String>());
        }    } else {
        




        let mut lineTail: bool = end + 1 >= (line.chars().count() as i64);
        if !(lineTail) {
            if !(seenCode) {
                title = Some("".to_string());
            }        }    }

    return Some(LinkScan { next: end + 1, text: text.to_string(), href: href.to_string(), loading: false, title: title, tail: "".to_string() });
}

fn extractAnchorBlock(text: &str) -> String {
    let t = text.trim().to_string();
    let parts = t.split(" ").map(|s| s.to_string()).collect::<Vec<String>>();
    let n: i64 = (parts.len() as i64);
    if n < 2 {
        return "".to_string();
    }
    let last = parts[(n - 1) as usize].clone();
    if (last.chars().count() as i64) < 2 {
        return "".to_string();
    }
    if last.chars().take((1) as usize).skip((0) as usize).collect::<String>() != "^" {
        return "".to_string();
    }
    let body = last.chars().skip((1) as usize).collect::<String>();
    let alphabet: String = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-".to_string();
    for i in 0..(body.chars().count() as i64) {
        let ch = body.chars().take((i + 1) as usize).skip((i) as usize).collect::<String>();
        let mut ok: bool = false;
        for j in 0..(alphabet.chars().count() as i64) {
            if alphabet.chars().take((j + 1) as usize).skip((j) as usize).collect::<String>() == ch {
                ok = true;
            }
        }
        if !(ok) {
            return "".to_string();
        }
    }
    return body;
}

fn convertInlines(wnodes: Vec<WNode>, mut marks: Vec<Mark>) -> Vec<InlineSpan> {
    let mut out: Vec<InlineSpan> = vec![];
    for w in &wnodes {
        let t: String = w.r#type.clone();
        if t == "text" {
            out.push(spanWith(w.content.clone().unwrap_or("".to_string()).as_str(), marks.clone(), vec![]));
        }
        if t == "strong" {
            for s in convertInlines(w.children.clone().unwrap_or(noNodes()), addMark(marks.clone(), Mark::Strong.clone())) {
                out.push(s.clone());
            }
        }
        if t == "emphasis" {
            for s in convertInlines(w.children.clone().unwrap_or(noNodes()), addMark(marks.clone(), Mark::Em.clone())) {
                out.push(s.clone());
            }
        }
        if t == "underline" {
            for s in convertInlines(w.children.clone().unwrap_or(noNodes()), addMark(marks.clone(), Mark::Underline.clone())) {
                out.push(s.clone());
            }
        }
        if t == "strikethrough" {
            for s in convertInlines(w.children.clone().unwrap_or(noNodes()), addMark(marks.clone(), Mark::Del.clone())) {
                out.push(s.clone());
            }
        }
        if t == "inline_code" {
            out.push(spanWith(w.code.clone().unwrap_or("".to_string()).as_str(), addMark(marks.clone(), Mark::Code.clone()), vec![]));
        }
        if t == "hardbreak" {
            out.push(spanWith("\n", marks.clone(), vec![]));
        }
        if t == "link" {
            let mut lattrs: Vec<Attr> = vec![];
            lattrs = attrSet(lattrs.clone(), "href", Value::Str(w.href.clone().unwrap_or("".to_string())));
            let title = w.title.clone();
            if title != None {
                lattrs = attrSet(lattrs.clone(), "title", Value::Str(title.unwrap_or("".to_string())));
            }            for s in convertInlines(w.children.clone().unwrap_or(noNodes()), addMark(marks.clone(), Mark::Link.clone())) {
                out.push(spanWith(s.text.as_str(), s.marks.clone(), lattrs.clone()));
            }
        }
        if t == "image" {
            let mut iattrs: Vec<Attr> = vec![];
            iattrs = attrSet(iattrs.clone(), "src", Value::Str(w.src.clone().unwrap_or("".to_string())));
            iattrs = attrSet(iattrs.clone(), "alt", Value::Str(w.alt.clone().unwrap_or("".to_string())));
            let ititle = w.title.clone();
            if ititle != None {
                iattrs = attrSet(iattrs.clone(), "title", Value::Str(ititle.unwrap_or("".to_string())));
            }            out.push(spanWith(w.alt.clone().unwrap_or("".to_string()).as_str(), addMark(marks.clone(), Mark::Image.clone()), iattrs.clone()));
        }
        if t == "wikilink" {
            




            let mut wattrs: Vec<Attr> = vec![];
            wattrs = attrSet(wattrs.clone(), "wikilink", Value::Str(w.title.clone().unwrap_or("".to_string())));
            out.push(spanWith(w.title.clone().unwrap_or("".to_string()).as_str(), marks.clone(), wattrs.clone()));
        }
        if t == "math_inline" {
            



            let mut mattrs: Vec<Attr> = vec![];
            mattrs = attrSet(mattrs.clone(), "math_inline", Value::Str(w.code.clone().unwrap_or("".to_string())));
            out.push(spanWith(w.code.clone().unwrap_or("".to_string()).as_str(), marks.clone(), mattrs.clone()));
        }
    }
    return out;
}

fn convertTableCell(wnode: WNode, id: &str) -> BlockNode {
    let mut attrs: Vec<Attr> = vec![];
    attrs = attrSet(attrs.clone(), "header", Value::Bool(wnode.isHeader.unwrap_or(false)));
    attrs = attrSet(attrs.clone(), "align", Value::Str(wnode.align.unwrap_or("left".to_string())));
    return blockFull(id, BlockType::TableCell.clone(), attrs.clone(), vec![], convertInlines(wnode.children.unwrap_or(noNodes()), vec![]), rng(0, 0));
}

fn convertTableRow(wnode: WNode, id: &str) -> BlockNode {
    let cells: Vec<WNode> = wnode.cells.unwrap_or(noNodes());
    let mut kids: Vec<BlockNode> = vec![];
    for ci in 0..(cells.len() as i64) {
        kids.push(convertTableCell(cells[(ci) as usize].clone(), format!("{}{}", format!("{}{}", id, "-c"), format!("{:?}", ci)).as_str()));
    }
    return blockFull(id, BlockType::TableRow.clone(), vec![], kids.clone(), vec![], rng(0, 0));
}

fn convertBlock(wnode: WNode, id: &str) -> BlockNode {
    let t: String = wnode.r#type.clone();
    if t == "heading" {
        let mut attrs: Vec<Attr> = vec![];
        attrs = attrSet(attrs.clone(), "level", Value::Int(wnode.level.unwrap_or(0)));
        return blockFull(id, BlockType::Heading.clone(), attrs.clone(), vec![], convertInlines(wnode.children.unwrap_or(noNodes()), vec![]), rng(0, 0));
    }
    if t == "code_block" {
        let mut attrs2: Vec<Attr> = vec![];
        attrs2 = attrSet(attrs2.clone(), "language", Value::Str(wnode.language.unwrap_or("".to_string())));
        attrs2 = attrSet(attrs2.clone(), "loading", Value::Bool(wnode.loading.unwrap_or(false)));
        return blockFull(id, BlockType::Fence.clone(), attrs2.clone(), vec![], vec![span(wnode.code.unwrap_or("".to_string()).as_str())], rng(0, 0));
    }
    if t == "blockquote" {
        return blockFull(id, BlockType::Blockquote.clone(), vec![], convertChildren(wnode.children.unwrap_or(noNodes()), id), vec![], rng(0, 0));
    }
    if t == "list" {
        let mut attrs3: Vec<Attr> = vec![];
        attrs3 = attrSet(attrs3.clone(), "ordered", Value::Bool(wnode.ordered.unwrap_or(false)));
        let start: Option<i64> = wnode.start.clone();
        if start != None {
            attrs3 = attrSet(attrs3.clone(), "start", Value::Int(start.unwrap_or(0)));
        }        return blockFull(id, BlockType::ListBlock.clone(), attrs3.clone(), convertChildren(wnode.items.unwrap_or(noNodes()), id), vec![], rng(0, 0));
    }
    if t == "list_item" {
        let mut attrsLI: Vec<Attr> = vec![];
        

        let ck: Option<bool> = wnode.checked.clone();
        if ck != None {
            attrsLI = attrSet(attrsLI.clone(), "checked", Value::Bool(ck.unwrap_or(false)));
        }        return blockFull(id, BlockType::ListItem.clone(), attrsLI.clone(), convertChildren(wnode.children.unwrap_or(noNodes()), id), vec![], rng(0, 0));
    }
    if t == "table" {
        let mut kids: Vec<BlockNode> = vec![];
        let hdr: Vec<WNode> = wnode.header.unwrap_or(noNodes());
        if (hdr.len() as i64) > 0 {
            kids.push(convertTableRow(hdr[0].clone(), format!("{}{}", id, "-h").as_str()));
        }        let rows: Vec<WNode> = wnode.rows.unwrap_or(noNodes());
        for ri in 0..(rows.len() as i64) {
            kids.push(convertTableRow(rows[(ri) as usize].clone(), format!("{}{}", format!("{}{}", id, "-r"), format!("{:?}", ri)).as_str()));
        }
        let mut attrs4: Vec<Attr> = vec![];
        attrs4 = attrSet(attrs4.clone(), "loading", Value::Bool(wnode.loading.unwrap_or(false)));
        return blockFull(id, BlockType::Table.clone(), attrs4.clone(), kids.clone(), vec![], rng(0, 0));
    }
    if t == "thematic_break" {
        return blockFull(id, BlockType::ThematicBreak.clone(), vec![], vec![], vec![], rng(0, 0));
    }
    if t == "callout" {
        let mut attrsC: Vec<Attr> = vec![];
        attrsC = attrSet(attrsC.clone(), "type", Value::Str(wnode.language.unwrap_or("".to_string())));
        attrsC = attrSet(attrsC.clone(), "title", Value::Str(wnode.title.unwrap_or("".to_string())));
        return blockFull(id, BlockType::Callout.clone(), attrsC.clone(), convertChildren(wnode.children.unwrap_or(noNodes()), id), vec![], rng(0, 0));
    }
    if t == "details" {
        let mut attrsD: Vec<Attr> = vec![];
        attrsD = attrSet(attrsD.clone(), "summary", Value::Str(wnode.text.unwrap_or("".to_string())));
        

        if wnode.loading.unwrap_or(false) {
            attrsD = attrSet(attrsD.clone(), "open", Value::Bool(true));
        }        return blockFull(id, BlockType::Details.clone(), attrsD.clone(), convertChildren(wnode.children.unwrap_or(noNodes()), id), vec![], rng(0, 0));
    }
    if t == "query" {
        let mut attrsQ: Vec<Attr> = vec![];
        attrsQ = attrSet(attrsQ.clone(), "query", Value::Str(wnode.content.unwrap_or("".to_string())));
        return blockFull(id, BlockType::QueryBlock.clone(), attrsQ.clone(), vec![], vec![], rng(0, 0));
    }
    if t == "embed" {
        let mut attrsE: Vec<Attr> = vec![];
        attrsE = attrSet(attrsE.clone(), "src", Value::Str(wnode.src.unwrap_or("".to_string())));
        return blockFull(id, BlockType::BlockEmbed.clone(), attrsE.clone(), vec![], vec![], rng(0, 0));
    }
    if t == "math_block" {
        return blockFull(id, BlockType::MathBlock.clone(), vec![], vec![], vec![span(wnode.code.unwrap_or("".to_string()).as_str())], rng(0, 0));
    }
    if t == "mermaid" {
        return blockFull(id, BlockType::Mermaid.clone(), vec![], vec![], vec![span(wnode.code.unwrap_or("".to_string()).as_str())], rng(0, 0));
    }

    return blockFull(id, BlockType::Paragraph.clone(), vec![], vec![], convertInlines(wnode.children.unwrap_or(noNodes()), vec![]), rng(0, 0));
}

fn convertChildren(mut wchildren: Vec<WNode>, parentId: &str) -> Vec<BlockNode> {
    let mut out: Vec<BlockNode> = vec![];
    for i in 0..(wchildren.len() as i64) {
        out.push(convertBlock(wchildren[(i) as usize].clone(), format!("{}{}", format!("{}{}", parentId, "-"), format!("{:?}", i)).as_str()));
    }
    return out;
}

fn intListToValue(mut arr: Vec<Option<i64>>) -> Value {
    let mut out: Vec<Value> = vec![];
    let mut i: i64 = 0;
    while i < (arr.len() as i64) {
        let v = arr[(i) as usize].clone();
        if v == None {
            out.push(Value::Null);
        } else {
            out.push(Value::Int(v.unwrap_or(0)));
        }

        i += 1;
    }
    return Value::ListV(out);
}

fn attachIAL(blocks: Vec<BlockNode>, mut ialAttrs: Vec<TableAttr>) -> Vec<BlockNode> {
    let mut out: Vec<BlockNode> = vec![];
    let mut ti: i64 = 0;
    for b in &blocks {
        if b.kind == BlockType::Table {
            if ti < (ialAttrs.len() as i64) {
                let ta = ialAttrs[(ti) as usize].clone();
                let cols = intListToValue(ta.cols.clone());
                let rows = intListToValue(ta.rows.clone());
                let mut ialPair: Vec<Attr> = vec![];
                ialPair.push(attrOf("cols", cols.clone()));
                ialPair.push(attrOf("rows", rows.clone()));
                out.push(blockFull(b.id.as_str(), b.kind.clone(), attrSet(b.attrs.clone(), "ial", Value::AttrsV(ialPair)), b.children.clone(), b.inlines.clone(), b.source.clone()));
                ti += 1;
            } else {
                out.push(b.clone().clone());
            }
        } else {
            out.push(b.clone().clone());
        }

    }
    return out;
}

fn withAnchorId(node: BlockNode, fallbackId: &str) -> BlockNode {
    let anchor = extractAnchorBlock(spansText(node.inlines.clone()).as_str());
    if anchor == "" {
        return node;
    }
    return blockFull(anchor.as_str(), node.kind.clone(), node.attrs.clone(), node.children.clone(), node.inlines.clone(), node.source.clone());
}

fn endsWithTokSeq(hay: &str, needle: &str) -> bool {
    let hl: i64 = (hay.chars().count() as i64);
    let nl: i64 = (needle.chars().count() as i64);
    if nl > hl {
        return false;
    }
    return hay.chars().take((hl) as usize).skip((hl - nl) as usize).collect::<String>() == needle;
}

fn stripAnchorSpans(mut spans: Vec<InlineSpan>, cut: i64) -> Vec<InlineSpan> {
    let mut out: Vec<InlineSpan> = vec![];
    let mut pos: i64 = 0;
    for i in 0..(spans.len() as i64) {
        let t = spans[(i) as usize].clone().text;
        let start: i64 = pos;
        let end: i64 = pos + (t.chars().count() as i64);
        pos = end;
        if start >= cut {
            

        } else {
            if end <= cut {
                out.push(spans[(i) as usize].clone());
            } else {
                let keepLen: i64 = cut - start;
                if keepLen > 0 {
                    out.push(spanWith(t.chars().take((keepLen) as usize).skip((0) as usize).collect::<String>().as_str(), spans[(i) as usize].clone().marks.clone(), spans[(i) as usize].clone().attrs.clone()));
                }            }
        }

    }
    return out;
}

fn isAnchorableLeafKind(kind: BlockType) -> bool {
    if kind == BlockType::Paragraph {
        return true;
    }
    if kind == BlockType::Heading {
        return true;
    }
    if kind == BlockType::ListItem {
        return true;
    }
    return false;
}

pub fn applyAnchorsDeep(node: BlockNode) -> BlockNode {
    let mut kids: Vec<BlockNode> = vec![];
    for i in 0..(node.children.len() as i64) {
        kids.push(applyAnchorsDeep(node.children[(i) as usize].clone()));
    }
    let mut out: BlockNode = blockFull(node.id.as_str(), node.kind.clone(), node.attrs.clone(), kids.clone(), node.inlines.clone(), node.source.clone());
    if isAnchorableLeafKind(node.kind.clone()) {
        if (node.inlines.len() as i64) > 0 {
            let text = spansText(node.inlines.clone());
            let anchor = extractAnchorBlock(text.as_str());
            if anchor != "" {
                let total: i64 = (text.chars().count() as i64);
                let tokLen: i64 = (anchor.chars().count() as i64) + 1;
                let spaceIdx: i64 = total - tokLen - 1;
                if spaceIdx >= 0 {
                    let ws = text.chars().take((spaceIdx + 1) as usize).skip((spaceIdx) as usize).collect::<String>();
                    if ws == " " || ws == "\t" {
                        let stripped = stripAnchorSpans(node.inlines.clone(), spaceIdx);
                        let base = blockFull(node.id.as_str(), node.kind.clone(), node.attrs.clone(), kids.clone(), stripped.clone(), node.source.clone());
                        out = withIdAndAnchor(base.clone(), anchor.as_str());
                    }                }            }        }    }
    return out;
}

fn stripLineAnchor(l: &str) -> String {
    let n: i64 = (l.chars().count() as i64);
    if n < 3 {
        return l.to_string();
    }
    let cand = extractAnchorBlock(l);
    if cand == "" {
        return l.to_string();
    }
    let tok: String = format!("{}{}", "^", cand);
    let tokLen: i64 = (tok.chars().count() as i64);
    if !(endsWithTokSeq(l, tok.as_str())) {
        return l.to_string();
    }
    let before: i64 = n - tokLen;
    if before <= 0 {
        return l.to_string();
    }
    let ws = l.chars().take((before) as usize).skip((before - 1) as usize).collect::<String>();
    if ws != " " && ws != "\t" {
        return l.to_string();
    }
    return l.chars().take((before - 1) as usize).skip((0) as usize).collect::<String>().to_string();
}

pub fn stripAnchorTokens(md: &str) -> String {
    let mut out: String = "".to_string();
    let mut inFence: bool = false;
    let lines = md.split("\n").map(|s| s.to_string()).collect::<Vec<String>>();
    let count: i64 = (lines.len() as i64);
    for i in 0..count {
        let mut l: String = lines[(i) as usize].clone();
        if l.chars().take((3) as usize).skip((0) as usize).collect::<String>() == "```" {
            inFence = !(inFence);
        } else {
            if !(inFence) {
                l = stripLineAnchor(l.as_str());
            }        }

        out = format!("{}{}", out, l);
        if i < count - 1 {
            out = format!("{}{}", out, "\n");
        }
    }
    return out;
}

pub fn parse_blocks(src: &str, isFinal: bool) -> BlockNode {
    let pre = preprocessMarkdown(src);
    let preMd = pre.md.clone();
    let weak = parseDocument(preMd.as_str(), isFinal);
    let mut kids: Vec<BlockNode> = vec![];
    for i in 0..(weak.len() as i64) {
        let fallback: String = format!("{}{}", "block-", format!("{:?}", i));
        kids.push(applyAnchorsDeep(convertBlock(weak[(i) as usize].clone(), fallback.as_str())));
    }
    let withIal = attachIAL(kids.clone(), pre.tableAttrs.clone());
    return blockFull("doc", BlockType::Paragraph.clone(), vec![], withIal.clone(), vec![], rng(0, 0));
}
